        int64_t row_start = (i - col) * 2; // (row*D)*2 = row*2D
        float gate = to_float<T>(x[row_start + col]);
        float up   = to_float<T>(x[row_start + D + col]);
        y[i] = from_float<T>(swiglu_f(gate, up));
